
const $=id=>document.getElementById(id),KEY='recomp10m_state';let state={workouts:[],records:{},weights:[81],metrics:[],photos:[],readiness:75,recovery:{water:2},goals:{protein:false,water:false,sleep:false},macros:{kcal:2850,p:170,c:360,f:75},mealPlan:[],prefs:{autoDeload:true,autoTimer:true,theme:"blue",autopilot:true},learning:{},decisions:[],sessionSwaps:{}};try{state={...state,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{};state.prefs={autoDeload:true,autoTimer:true,theme:"blue",autopilot:true,...state.prefs};state.learning=state.learning||{};state.decisions=state.decisions||[];state.sessionSwaps=state.sessionSwaps||{};state.macros={kcal:2850,p:170,c:360,f:75,...state.macros};state.goals={protein:false,water:false,sleep:false,...state.goals};let currentDay=0,recipeFilter='Todos',timerId=null,timerSeconds=90;function persist(){localStorage.setItem(KEY,JSON.stringify(state))}function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',1800)}function go(id){document.querySelectorAll('.screen').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.target===id));if(id==='progress')renderProgress();if(id==='library')renderLibrary();if(id==='insights'){renderInsights();renderIntelligence();}if(id==='analytics')renderAnalytics();if(id==='training')renderSportWorkspace();if(id==='nutrition')renderSportNutrition();scrollTo(0,0)}function daysAgo(d){return(Date.now()-new Date(d))/864e5}function weekWorkouts(){return state.workouts.filter(w=>daysAgo(w.date)<=7).length}function weekVolume(){return state.workouts.filter(w=>daysAgo(w.date)<=7).reduce((s,w)=>s+w.volume,0)}function monthPR(){return state.workouts.filter(w=>daysAgo(w.date)<=30).reduce((s,w)=>s+w.prs,0)}function streak(){let dates=[...new Set(state.workouts.map(w=>new Date(w.date).toISOString().slice(0,10)))].sort().reverse();if(!dates.length)return 0;let s=1;for(let i=1;i<dates.length;i++){if((new Date(dates[i-1])-new Date(dates[i]))/864e5<=1.1)s++;else break}return s}function lastFor(name){for(let i=state.workouts.length-1;i>=0;i--){const e=state.workouts[i].exercises.find(x=>x.name===name),d=e?.sets.filter(s=>s.done);if(d?.length)return d.at(-1)}return null}function historyFor(name){return state.workouts.flatMap(w=>{const e=w.exercises.find(x=>x.name===name);return e?e.sets.filter(s=>s.done):[]})}function recommend(e){let h=historyFor(e.name),hi=+(e.range.match(/\d+/g)||[12]).at(-1);if(!h.length)return'Empieza conservador, técnica limpia y 2–3 RIR.';let l=h.at(-1);if(l.reps>=hi&&l.rir>=1)return`Sube a ${Math.round((l.kg+2.5)*2)/2} kg y mantén el rango.`;if(l.rir===0)return`Mantén ${l.kg} kg y evita el fallo esta vez.`;return`Repite ${l.kg} kg e intenta ${Math.min(hi,l.reps+1)} repeticiones.`}function coachMessage(){if(state.readiness<45)return'Recuperación baja: reduce volumen, mantén 3 RIR y prioriza técnica.';if(state.readiness<65)return'Día medio: conserva cargas y evita llegar al fallo.';if(weekWorkouts()>=4)return'Objetivo semanal cumplido. Entrena solo si te sientes recuperado.';return'Buena preparación: busca una progresión pequeña en un ejercicio.'}function renderDashboard(){let w=state.weights.at(-1)||81,prev=state.weights.at(-2);$('homeWeight').textContent=w.toFixed(1).replace('.',',')+' kg';$('weightTrend').textContent=prev?`${w-prev>=0?'+':''}${(w-prev).toFixed(1)} kg desde el último registro`:'Primer registro';let adh=Math.min(100,Math.round(weekWorkouts()/4*100));$('adherence').textContent=adh+'%';$('adhBar').style.width=adh+'%';$('coachHeadline').textContent=coachMessage();$('readyScore').textContent=state.readiness;$('readyRing').style.setProperty('--n',state.readiness);$('weekVolume').textContent=weekVolume().toLocaleString();$('monthPR').textContent=monthPR();$('streak').textContent=streak()+' d';renderGoals();renderRIS()}function saveRecovery(){let total=+$('sleep').value + +$('energy').value + +$('stress').value + +$('pain').value;let water=+$('water').value||state.recovery.water||2;state.recovery={water,date:new Date().toISOString()};state.readiness=Math.min(100,Math.round(total/12*90+Math.min(10,water/3*10)));persist();renderDashboard();renderExercises();toast('Recuperación actualizada')}function renderGoals(){const labels={protein:'Cumplir proteína 5 días',water:'Beber 3 L durante 5 días',sleep:'Dormir 7 h durante 5 días'};$('goals').innerHTML=`<div class="listitem"><div><b>Completar 4 entrenamientos</b><div class="small">${weekWorkouts()} de 4</div></div><span class="pill ${weekWorkouts()>=4?'':'warn'}">${weekWorkouts()>=4?'Hecho':'En curso'}</span></div>`+Object.entries(labels).map(([k,v])=>`<label class="listitem"><span><b>${v}</b><div class="small">${state.goals[k]?'Completado':'Pendiente'}</div></span><input type="checkbox" style="width:22px" ${state.goals[k]?'checked':''} onchange="state.goals.${k}=this.checked;persist();renderGoals()"></label>`).join('')}function renderDayTabs(){$('dayTabs').innerHTML=PROGRAM.map((d,i)=>`<button class="tab ${i===currentDay?'active':''}" onclick="currentDay=${i};renderDayTabs();renderExercises()">${d.day}</button>`).join('')}function exerciseByName(name){return EXERCISE_LIBRARY.find(x=>x.name===name)||PROGRAM.flatMap(d=>d.exercises).find(x=>x.name===name)||{name,muscle:'General',equipment:'Variable',range:'8–12',rest:90,alt:[]}}
function movementGuide(e){const m=(e.muscle||'').toLowerCase(),n=e.name.toLowerCase();let setup=['Coloca el cuerpo estable y ajusta el material antes de empezar.','Usa una carga que permita completar el rango con 1–3 RIR.'];let execution=['Inicia la repetición de forma controlada.','Recorre una amplitud cómoda sin perder la posición.','Vuelve a la posición inicial sin rebotes.'];let cues=['Respira y crea tensión antes de mover la carga.','Mantén el movimiento controlado, especialmente en la bajada.'];let mistakes=['Usar impulso','Acortar el recorrido','Perder la posición por exceso de carga'];
if(m.includes('pecho')){setup=['Retracción escapular suave y pies firmes.','Alinea muñeca, codo y hombro.'];execution=['Baja la carga hacia la línea media del pecho de forma controlada.','Mantén los antebrazos estables.','Empuja sin despegar hombros ni glúteos.'];cues=['Pecho alto, hombros lejos de las orejas.','Piensa en acercar los brazos, no solo en empujar.']}
if(m.includes('espalda')){setup=['Pecho estable y columna neutra.','Inicia con hombros relajados, sin encogerlos.'];execution=['Comienza llevando escápulas y codos hacia atrás o abajo.','Pausa brevemente en la contracción.','Regresa con control hasta notar estiramiento.'];cues=['Tira con los codos.','Evita convertir el ejercicio en un movimiento lumbar.']}
if(m.includes('cuádriceps')){setup=['Apoya todo el pie y alinea rodilla con los dedos.','Ajusta la profundidad a tu movilidad y ausencia de dolor.'];execution=['Desciende controlando cadera y rodillas.','Mantén el tronco estable.','Empuja el suelo para volver sin bloquear agresivamente.'];cues=['Rodilla sigue la dirección del pie.','Carga repartida en todo el pie.']}
if(m.includes('femoral')||m.includes('glúteo')){setup=['Columna neutra y abdomen activo.','Coloca la cadera para sentir tensión posterior.'];execution=['Lleva la cadera atrás o extiéndela según el ejercicio.','Mantén la carga cerca del cuerpo cuando corresponda.','Finaliza contrayendo glúteos sin hiperextender la espalda.'];cues=['La cadera dirige el movimiento.','Siente tensión, no dolor lumbar.']}
if(m.includes('hombro')){setup=['Costillas controladas y cuello relajado.','Usa una carga que no obligue a balancear el torso.'];execution=['Mueve el brazo en un plano cómodo.','Evita encoger el hombro.','Baja más lento de lo que subes.'];cues=['Hombros abajo.','Control antes que peso.']}
if(m.includes('core')){setup=['Columna y pelvis en posición neutra.','Activa el abdomen antes de comenzar.'];execution=['Mantén tensión mientras respiras.','Evita que la zona lumbar cambie de posición.','Termina la serie cuando pierdas control.'];cues=['Costillas hacia pelvis.','Respira sin soltar el abdomen.']}
return{setup,execution,cues,mistakes};}
function motionPattern(e){const n=e.name.toLowerCase(),m=(e.muscle||'').toLowerCase();if(/sentadilla|prensa|extensi[oó]n de cu[aá]driceps/.test(n))return'squat';if(/peso muerto|rumano|hip thrust|puente|good morning/.test(n))return'hinge';if(/zancada|split squat|step up/.test(n))return'lunge';if(/remo|jal[oó]n|dominada|face pull/.test(n))return'pull';if(/press|flexi[oó]n|fondos/.test(n))return'push';if(/curl/.test(n))return'curl';if(/elevaci[oó]n|p[aá]jaro|apertura/.test(n))return'raise';if(/plancha|crunch|abdominal|pallof|dead bug/.test(n)||m.includes('core'))return'core';return m.includes('espalda')?'pull':m.includes('pecho')||m.includes('hombro')?'push':m.includes('pierna')||m.includes('glúteo')?'squat':'curl'}
function motionDemo(e){const p=motionPattern(e);return`<div class="motion-stage" data-pattern="${p}" id="motionStage"><svg viewBox="0 0 320 180" role="img" aria-label="Animación de ejemplo para ${e.name}"><line class="floor" x1="30" y1="150" x2="290" y2="150"/><g class="person"><circle class="joint" cx="160" cy="48" r="13"/><path class="body" d="M160 62 L160 104 L137 137 M160 104 L187 137"/><path class="body arm" d="M160 76 L126 101 L102 94"/><path class="body forearm" d="M160 76 L195 105 L220 96"/><circle class="weight" cx="99" cy="94" r="9"/><circle class="weight" cx="223" cy="96" r="9"/></g><path class="motion-arrow" d="M255 125 Q285 90 255 55"/></svg><div class="motion-caption"><b>Demostración animada:</b> observa el recorrido, el control y la posición general. Usa la guía escrita para ajustar la técnica.</div></div><div class="motion-controls"><button class="secondary" onclick="document.getElementById('motionStage').classList.toggle('paused');this.textContent=this.textContent.includes('Pausar')?'▶ Reanudar':'⏸ Pausar'">⏸ Pausar</button><button class="secondary" onclick="document.getElementById('motionStage').style.transform='scaleX('+((document.getElementById('motionStage').style.transform||'').includes('-1')?'1':'-1')+')'">↔ Cambiar lado</button></div>`}
function openExerciseGuide(name){const e=exerciseByName(name),g=movementGuide(e);let el=document.getElementById('exerciseGuideModal');if(!el){el=document.createElement('div');el.id='exerciseGuideModal';el.className='modal';document.body.appendChild(el)}el.innerHTML=`<div class="sheet"><div class="row"><div><span class="pill">MOTION COACH</span><h2>${e.name}</h2><div class="small">${e.muscle} · ${e.equipment} · ${e.range}</div></div><button class="secondary" onclick="this.closest('.modal').classList.remove('open')">Cerrar</button></div>${motionDemo(e)}<div class="guide-card"><h4>1. Preparación</h4><ol class="guide-steps">${g.setup.map(x=>`<li>${x}</li>`).join('')}</ol></div><div class="guide-card"><h4>2. Ejecución</h4><ol class="guide-steps">${g.execution.map(x=>`<li>${x}</li>`).join('')}</ol></div><div class="guide-card"><h4>Claves técnicas</h4>${g.cues.map(x=>`<div class="cue">✓ ${x}</div>`).join('')}</div><div class="warning-box"><b>Errores frecuentes:</b> ${g.mistakes.join(' · ')}</div><div class="success-box" style="margin-top:9px"><b>Intensidad recomendada:</b> termina la mayoría de series con 1–3 repeticiones en reserva y detente si aparece dolor articular.</div></div>`;el.classList.add('open')}
function getSessionExercise(di,ei){const base=PROGRAM[di].exercises[ei],key=di+'-'+ei,name=state.sessionSwaps?.[key];return name?{...exerciseByName(name),sets:base.sets,rest:base.rest,range:exerciseByName(name).range||base.range,original:base.name}:base}
function renderExercises(){state.sessionSwaps=state.sessionSwaps||{};let d=PROGRAM[currentDay],reduce=state.prefs.autoDeload&&state.readiness<60;$('exerciseList').innerHTML=`<div class="card"><div class="row"><div><h3 class="sectionTitle">${d.name}</h3><span class="small">${d.focus}</span></div><span class="pill ${reduce?'warn':''}">${reduce?'Volumen ajustado':'Sesión normal'}</span></div></div>`+d.exercises.map((base,ei)=>{let e=getSessionExercise(currentDay,ei),l=lastFor(e.name),sets=reduce?Math.max(2,e.sets-1):e.sets,changed=e.original?`<div class="small" style="color:var(--amber)">Sustituye a: ${e.original}</div>`:'';return`<div class="exercise"><div class="row"><div><b>${e.name}</b><div class="small">${e.muscle} · ${e.range} · ${e.rest}s</div>${changed}</div><span class="equipment-tag">${e.equipment}</span></div><div class="guide-actions"><button class="secondary" onclick="openExerciseGuide('${e.name.replace(/'/g,"\'")}')">▶ Ver ejecución</button><button class="secondary" onclick="showAlternative(${currentDay},${ei})">⇄ Alternativas</button></div><div class="coach"><b>Coach:</b> ${recommend(e)}</div><div class="setrow"><span>#</span><span>kg</span><span>reps</span><span>RIR</span><span></span></div>${Array.from({length:sets},(_,si)=>`<div class="setrow"><b>${si+1}</b><input id="kg-${ei}-${si}" type="number" step="0.5" value="${l?.kg??''}"><input id="rp-${ei}-${si}" type="number" value="${l?.reps??''}"><select id="rir-${ei}-${si}"><option>3</option><option selected>2</option><option>1</option><option>0</option></select><input id="dn-${ei}-${si}" type="checkbox" onchange="if(this.checked&&state.prefs.autoTimer)timerStart(${e.rest})"></div>`).join('')}<textarea id="note-${ei}" placeholder="Notas de técnica o molestias"></textarea></div>`}).join('')}
function showAlternative(di,ei){state.sessionSwaps=state.sessionSwaps||{};const base=PROGRAM[di].exercises[ei],current=getSessionExercise(di,ei);let names=[base.name,...base.alt,...EXERCISE_LIBRARY.filter(x=>x.muscle===base.muscle&&x.name!==base.name&&!base.alt.includes(x.name)).slice(0,4).map(x=>x.name)];names=[...new Set(names)];let el=document.getElementById('alternativesModal');if(!el){el=document.createElement('div');el.id='alternativesModal';el.className='modal';document.body.appendChild(el)}el.innerHTML=`<div class="sheet"><div class="row"><div><span class="pill">SELECTOR DE ALTERNATIVAS</span><h2>${base.name}</h2><p class="small">Escoge según material, comodidad o molestias. Se mantiene el grupo muscular y un estímulo parecido.</p></div><button class="secondary" onclick="this.closest('.modal').classList.remove('open')">Cerrar</button></div>${names.map(n=>{const x=exerciseByName(n),sel=n===current.name;return`<div class="alt-card ${sel?'selected':''}"><div class="row"><div><b>${n}</b><div class="small">${x.muscle||base.muscle} · ${x.equipment||'Material variable'} · ${x.range||base.range}</div></div>${sel?'<span class="pill">En uso</span>':''}</div><div class="guide-actions"><button class="secondary" onclick="openExerciseGuide('${n.replace(/'/g,"\'")}')">Ver ejecución</button><button class="primary" onclick="selectAlternative(${di},${ei},'${n.replace(/'/g,"\'")}')">Elegir</button></div></div>`}).join('')}</div>`;el.classList.add('open')}
function selectAlternative(di,ei,name){state.sessionSwaps=state.sessionSwaps||{};const base=PROGRAM[di].exercises[ei];if(name===base.name)delete state.sessionSwaps[di+'-'+ei];else state.sessionSwaps[di+'-'+ei]=name;persist();document.getElementById('alternativesModal')?.classList.remove('open');renderExercises();toast('Ejercicio actualizado: '+name)}function timerStart(s){timerStop();timerSeconds=s;$('timerText').textContent=fmt(s);timerId=setInterval(()=>{timerSeconds--;$('timerText').textContent=fmt(timerSeconds);if(timerSeconds<=0){timerStop();toast('Descanso completado')}},1000)}function timerStop(){clearInterval(timerId);timerId=null}function fmt(s){return`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}function finishWorkout(){let d=PROGRAM[currentDay],volume=0,prs=0,reduce=state.prefs.autoDeload&&state.readiness<60;let exercises=d.exercises.map((base,ei)=>{let e=getSessionExercise(currentDay,ei);let sets=[],count=reduce?Math.max(2,e.sets-1):e.sets;for(let si=0;si<count;si++){let done=$(`dn-${ei}-${si}`).checked,kg=+$(`kg-${ei}-${si}`).value||0,reps=+$(`rp-${ei}-${si}`).value||0,rir=+$(`rir-${ei}-${si}`).value;sets.push({done,kg,reps,rir});if(done){volume+=kg*reps;let score=kg*(1+reps/30),old=state.records[e.name]?.score||0;if(score>old){state.records[e.name]={kg,reps,score,date:new Date().toISOString()};prs++}}}return{name:e.name,sets,note:$(`note-${ei}`).value}});if(!exercises.some(e=>e.sets.some(s=>s.done)))return toast('Marca al menos una serie');state.workouts.push({date:new Date().toISOString(),day:d.day,name:d.name,volume:Math.round(volume),prs,readiness:state.readiness,exercises});persist();renderDashboard();renderExercises();toast(`Sesión guardada · ${Math.round(volume)} kg · ${prs} PR`)}function renderMacroTargets(){$('targetKcal').textContent=state.macros.kcal;$('targetProtein').textContent=state.macros.p+' g';$('targetCarbs').textContent=state.macros.c+' g';$('targetFat').textContent=state.macros.f+' g'}function renderRecipeTabs(){let t=['Todos','Desayuno','Comida','Cena','Snack'];$('recipeTabs').innerHTML=t.map(x=>`<button class="tab ${x===recipeFilter?'active':''}" onclick="recipeFilter='${x}';renderRecipeTabs();renderRecipes()">${x}</button>`).join('')}function renderRecipes(){let q=$('recipeSearch').value.toLowerCase(),list=ALL_RECIPES.filter(r=>(recipeFilter==='Todos'||r.type===recipeFilter)&&r.name.toLowerCase().includes(q));$('recipeCount').textContent=list.length.toLocaleString('es-ES');$('recipeList').innerHTML=list.slice(0,120).map((r,i)=>`<div class="meal" onclick="openRecipe('${r.id}')"><div class="row"><div><b>${r.name}</b><span class="small">${r.type} · ${r.p}P · ${r.c}C · ${r.f}G</span></div><span class="macro">${r.kcal} kcal</span></div></div>`).join('')||'<p class="muted">Sin resultados.</p>'}function generateMealPlan(){let types=['Desayuno','Comida','Snack','Cena'];state.mealPlan=types.map(t=>{let a=ALL_RECIPES.filter(r=>r.type===t);return a[Math.floor(Math.random()*a.length)]});persist();renderMealPlan()}function renderMealPlan(){if(!state.mealPlan.length)generateMealPlan();let totals=state.mealPlan.reduce((a,r)=>({kcal:a.kcal+r.kcal,p:a.p+r.p,c:a.c+r.c,f:a.f+r.f}),{kcal:0,p:0,c:0,f:0});$('mealPlan').innerHTML=state.mealPlan.map(r=>`<div class="meal"><b>${r.name}</b><span class="small">${r.type} · ${r.kcal} kcal · ${r.p} g proteína</span></div>`).join('');$('mealTotal').textContent=`${totals.kcal} kcal · ${totals.p}P · ${totals.c}C · ${totals.f}G`}function buildShoppingList(){let items=[...new Set(state.mealPlan.flatMap(r=>r.ingredients))];$('shoppingList').innerHTML=items.map(x=>`<label class="listitem"><span>${x}</span><input type="checkbox" style="width:22px"></label>`).join('')}function openMacroEditor(){['Kcal','Protein','Carbs','Fat'].forEach(x=>$('edit'+x).value=state.macros[{Kcal:'kcal',Protein:'p',Carbs:'c',Fat:'f'}[x]]);$('macroModal').classList.add('open')}function closeModal(){$('macroModal').classList.remove('open')}function saveMacros(){state.macros={kcal:+$('editKcal').value||2850,p:+$('editProtein').value||170,c:+$('editCarbs').value||360,f:+$('editFat').value||75};persist();renderMacroTargets();closeModal();toast('Objetivos guardados')}function saveMetrics(){let weight=+$('weightInput').value,entry={date:new Date().toISOString(),weight:weight||null,waist:+$('waistInput').value||null,chest:+$('chestInput').value||null,arm:+$('armInput').value||null};if(!Object.values(entry).some((v,i)=>i&&v))return toast('Introduce al menos una métrica');state.metrics.push(entry);if(weight)state.weights.push(weight);persist();['weightInput','waistInput','chestInput','armInput'].forEach(id=>$(id).value='');renderDashboard();renderProgress();toast('Métricas guardadas')}function renderProgress(){let a=state.weights,max=Math.max(...a),min=Math.min(...a),range=Math.max(1,max-min);$('weightChart').innerHTML=a.slice(-12).map(v=>`<div class="bar" style="height:${35+(v-min)/range*115}px"><span>${v}</span></div>`).join('');$('weightSummary').textContent=`Inicio ${a[0]} kg · actual ${a.at(-1)} kg · cambio ${(a.at(-1)-a[0]).toFixed(1)} kg`;let first=state.metrics[0],last=state.metrics.at(-1);let text=state.workouts.length?`${state.workouts.length} sesiones registradas y ${Object.keys(state.records).length} ejercicios con récord personal.`:'Empieza a registrar entrenamientos para generar un análisis.';if(first&&last&&first!==last){let parts=['waist','chest','arm'].filter(k=>first[k]&&last[k]).map(k=>`${k==='waist'?'Cintura':k==='chest'?'Pecho':'Brazo'}: ${last[k]-first[k]>=0?'+':''}${(last[k]-first[k]).toFixed(1)} cm`);if(parts.length)text+=' '+parts.join(' · ')}$('progressReport').innerHTML=`<p>${text}</p><div class="coach">${coachMessage()}</div>`;renderPhotos()}function addPhoto(ev){let f=ev.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{state.photos.push({date:new Date().toISOString(),src:r.result});if(state.photos.length>9)state.photos.shift();try{persist()}catch{state.photos.pop();toast('Imagen demasiado grande');return}renderPhotos();toast('Foto añadida')};r.readAsDataURL(f)}function renderPhotos(){$('photoGrid').innerHTML=state.photos.map(p=>`<div class="photo"><img src="${p.src}"><small>${new Date(p.date).toLocaleDateString()}</small></div>`).join('')||'<p class="small muted">Añade fotos para comparar visualmente tu progreso.</p>'}function renderLibrary(){let q=$('exerciseSearch').value.toLowerCase(),m=$('muscleFilter').value,list=EXERCISE_LIBRARY.filter(e=>e.name.toLowerCase().includes(q)&&(m==='Todos'||e.muscle===m));$('libraryList').innerHTML=list.map(e=>`<div class="libraryItem"><div class="row"><div><b>${e.name}</b><div class="small">${e.muscle} · ${e.equipment}</div></div><span class="pill">${e.range}</span></div><div class="guide-actions"><button class="secondary" onclick="openExerciseGuide('${e.name.replace(/'/g,"\'")}')">▶ Ejecución</button><button class="secondary" onclick="openLibraryAlternatives('${e.name.replace(/'/g,"\'")}')">⇄ Variantes</button></div></div>`).join('')||'<p class="muted">Sin resultados.</p>'}
function openLibraryAlternatives(name){const e=exerciseByName(name),pool=[...(e.alt||[]),...EXERCISE_LIBRARY.filter(x=>x.muscle===e.muscle&&x.name!==name).slice(0,5).map(x=>x.name)];let el=document.getElementById('libraryAltModal');if(!el){el=document.createElement('div');el.id='libraryAltModal';el.className='modal';document.body.appendChild(el)}el.innerHTML=`<div class="sheet"><div class="row"><div><span class="pill">VARIANTES</span><h2>${name}</h2></div><button class="secondary" onclick="this.closest('.modal').classList.remove('open')">Cerrar</button></div>${[...new Set(pool)].map(n=>`<div class="alt-card"><b>${n}</b><div class="small">${exerciseByName(n).equipment||'Material variable'} · ${exerciseByName(n).range||e.range}</div><button class="secondary" style="width:100%;margin-top:8px" onclick="openExerciseGuide('${n.replace(/'/g,"\'")}')">Ver ejecución</button></div>`).join('')}</div>`;el.classList.add('open')}
