function imageStats(img){let c=document.createElement('canvas'),w=160,h=Math.round(160*img.naturalHeight/img.naturalWidth);c.width=w;c.height=h;let x=c.getContext('2d');x.drawImage(img,0,0,w,h);let d=x.getImageData(0,0,w,h).data,sum=0,sum2=0,dark=0;for(let i=0;i<d.length;i+=4){let y=.2126*d[i]+.7152*d[i+1]+.0722*d[i+2];sum+=y;sum2+=y*y;if(y<75)dark++}let n=d.length/4,mean=sum/n,sd=Math.sqrt(sum2/n-mean*mean);return{mean,sd,dark:dark/n*100,ratio:img.naturalWidth/img.naturalHeight}}
