function currentSport(){return SPORT_ENGINE[state.prefs.sport||'hypertrophy']||SPORT_ENGINE.hypertrophy}
function setSport(key){state.prefs.sport=key;state.sportTab='today';persist();renderSportEngine();renderSportWorkspace();renderSportNutrition();toast('Modalidad: '+SPORT_ENGINE[key].name)}
function renderSportEngine(){
 const key=state.prefs.sport||'hypertrophy',sp=currentSport();
 if($('sportGrid'))$('sportGrid').innerHTML=Object.entries(SPORT_ENGINE).map(([k,v])=>`<button class="sport-card ${k===key?'active':''}" onclick="setSport('${k}')"><span class="emoji">${v.emoji}</span><b>${v.name}</b><small>${v.desc}</small></button>`).join('');
 if($('activeSportLabel'))$('activeSportLabel').textContent=sp.name;
 if($('sportDashboard'))$('sportDashboard').innerHTML=sp.metrics.map(([a,b])=>`<div class="sport-kpi"><span class="small">${a}</span><strong>${b}</strong></div>`).join('');
 if($('sportModules'))$('sportModules').innerHTML=sp.modules.map((m,i)=>`<button class="module-button" onclick="openSportModule('${m.replace(/'/g,"\\'")}')"><span><b>${m}</b><small style="display:block;color:var(--muted)">${i<2?'Disponible en Alpha':'Preparado para ampliación'}</small></span><span>›</span></button>`).join('');
 if($('sportNutrition'))$('sportNutrition').innerHTML=`<p>${sp.nutrition}</p><button class="secondary" onclick="go('nutrition')">Abrir nutrición adaptada</button>`;
 if($('sportCoach'))$('sportCoach').textContent=sp.coach;
 if($('homeSportName'))$('homeSportName').textContent=sp.name;if($('homeSportEmoji'))$('homeSportEmoji').textContent=sp.emoji;
}
function openSportModule(name){toast(name+' seleccionado'); if(/rutina|wod|rodaje|plan|dominadas/i.test(name))go('training'); else if(/nutrición/i.test(name))go('nutrition'); else go('library')}


