function world(){return SPORT_WORLDS[state.prefs.sport||'hypertrophy']||SPORT_WORLDS.hypertrophy}
function sportStyle(){let w=world();return `--sportA:${w.colors[0]};--sportB:${w.colors[1]}`}
function renderSportWorkspace(){const key=state.prefs.sport||'hypertrophy',sp=currentSport(),w=world();state.sportTab=state.sportTab||w.tabs[0].toLowerCase();let tab=state.sportTab;let html=`<div style="${sportStyle()}"><div class="sport-hero"><span class="pill">${sp.emoji} ${sp.name.toUpperCase()}</span><h2>${w.today.title}</h2><p class="muted">${w.today.subtitle}</p>${w.today.format?`<div class="wod-clock">${w.today.format}</div>`:''}<button class="primary" onclick="startSportSession()">${key==='crosstraining'?'INICIAR WOD':'INICIAR SESIÓN'}</button></div><div class="sport-nav">${w.tabs.map((x,i)=>`<button class="${tab===x.toLowerCase()||(!tab&&i===0)?'active':''}" onclick="state.sportTab='${x.toLowerCase()}';persist();renderSportWorkspace()">${x}</button>`).join('')}</div>`;
 if(tab===w.tabs[0].toLowerCase()||!w.tabs.includes(w.tabs.find(x=>x.toLowerCase()===tab))) html+=renderTodayWorld(w,key);
 else if(/skill|obstáculo|estaciones|ejercicios|técnica/.test(tab)) html+=renderSportLibrary(w);
 else if(/benchmark|tests|récords|splits|zonas|desnivel/.test(tab)) html+=renderSportMetrics(w,key);
 else html+=renderSportPlan(w,key);
 $('sportWorkspace').innerHTML=html+'</div>';
 const n=document.querySelector('nav button[data-target="training"]');if(n){n.querySelector('.navicon').textContent=sp.emoji;n.childNodes[n.childNodes.length-1].textContent=key==='crosstraining'?'WOD':key==='running'||key==='trail'?'Correr':'Entreno'}
}
function renderTodayWorld(w,key){return `<div class="card"><div class="row"><div><h3 class="sectionTitle">Plan de hoy</h3><span class="small">Contenido específico de ${currentSport().name}</span></div><span class="pill">Adaptado</span></div>${w.today.blocks.map((b,i)=>`<div class="session-block"><span class="type">${b[0]}</span><div class="row"><div><b>${b[1]}</b><div class="small">${b[2]}</div></div><button class="secondary" onclick="openSportMovement('${b[1].replace(/'/g,"\\'")}')">Ver técnica</button></div>${i===0&&key==='crosstraining'?'<div class="logline"><input placeholder="Rondas"><input placeholder="Reps extra"></div>':''}</div>`).join('')}<button class="primary" onclick="finishSportSession()">Guardar resultado</button></div><div class="card"><h3 class="sectionTitle">Coach ${currentSport().name}</h3><div class="coach">${currentSport().coach}</div></div>`}
function renderSportLibrary(w){return `<div class="card"><h3 class="sectionTitle">Biblioteca específica</h3><p class="small">Solo movimientos y habilidades propios de esta modalidad.</p>${w.library.map(x=>`<div class="libraryItem"><div class="row"><div><b>${x}</b><div class="small">Técnica · progresiones · escalados · alternativas</div></div><button class="secondary" onclick="openSportMovement('${x.replace(/'/g,"\\'")}')">Abrir</button></div></div>`).join('')}</div>`}
function renderSportMetrics(w,key){const examples=key==='crosstraining'?['Fran · 6:42','Cindy · 17 rondas','Grace · 4:18']:key==='ocr'?['Dead hang · 1:12','Monkey bars · 92%','5K trail · 28:40']:key==='hyrox'?['SkiErg · 4:06','Sled push · 2:21','Running avg · 5:02/km']:key==='running'?['5K · 23:48','10K · 49:32','Z2 · 6:02/km']:['Test principal · sin registro','Carga semanal · objetivo','Tendencia · estable'];return `<div class="card"><h3 class="sectionTitle">Métricas de ${currentSport().name}</h3><div class="workout-score">${w.metrics.map((x,i)=>`<div><b>${i? '—':'82'}</b><div class="small">${x}</div></div>`).join('')}</div></div><div class="card"><h3>Historial específico</h3>${examples.map(x=>`<div class="benchmark"><span>${x}</span><button class="secondary">Registrar</button></div>`).join('')}</div>`}
function renderSportPlan(w,key){return `<div class="card"><h3 class="sectionTitle">Semana de ${currentSport().name}</h3>${['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'].map((d,i)=>`<div class="listitem"><div><b>${d}</b><div class="small">${i<4?w.today.blocks[i%w.today.blocks.length][1]:(i===5?'Sesión larga / específica':'Recuperación')}</div></div><span class="pill ${i===6?'warn':''}">${i===6?'RECOVERY':'PLAN'}</span></div>`).join('')}</div><div class="card"><h3>Contenido disponible</h3><div class="option-grid">${w.library.slice(0,6).map(x=>`<button class="option-card" onclick="openSportMovement('${x.replace(/'/g,"\\'")}')"><b>${x}</b><div class="small">Abrir ficha</div></button>`).join('')}</div></div>`}
function startSportSession(){toast('Sesión iniciada · '+currentSport().name)}
function finishSportSession(){state.workouts.push({date:new Date().toISOString(),volume:0,prs:0,sport:state.prefs.sport,exercises:[]});persist();renderDashboard();toast('Resultado guardado en '+currentSport().name)}
function openSportMovement(name){const w=world(),alts=w.alternatives[name]||w.library.filter(x=>x!==name).slice(0,3);const pattern=/run|trail|rodaje|interval/i.test(name)?'lunge':/pull|row|domin|rope|monkey/i.test(name)?'pull':/squat|wall|lunge|step/i.test(name)?'squat':/ski|burpee|thruster/i.test(name)?'push':'hinge';const html=`<div class="sheet" style="${sportStyle()}"><div class="row"><div><span class="primary-sport">MOVEMENT STUDIO</span><h2 style="margin:5px 0">${name}</h2></div><button class="secondary" onclick="closeSportMovement()">Cerrar</button></div><div class="movement-pro" id="sportMotion"><svg viewBox="0 0 320 180"><line x1="20" y1="155" x2="300" y2="155" stroke="var(--line)" stroke-width="4"/><g class="person" style="transform-origin:160px 105px;animation:${pattern==='squat'?'squatRep':pattern==='pull'?'pullRep':pattern==='push'?'pushRep':pattern==='lunge'?'lungeRep':'hingeRep'} 2.5s ease-in-out infinite"><circle cx="160" cy="48" r="16" fill="var(--sportA)"/><path d="M160 64 L160 108 M160 78 L125 98 M160 78 L198 96 M160 108 L135 148 M160 108 L190 148" stroke="var(--text)" stroke-width="9" stroke-linecap="round" fill="none"/><circle cx="125" cy="98" r="7" fill="var(--sportB)"/><circle cx="198" cy="96" r="7" fill="var(--sportB)"/></g><path d="M245 55 Q275 90 245 125" stroke="var(--sportA)" stroke-width="5" fill="none" stroke-dasharray="9 7"/></svg></div><div class="angle-switch"><button class="active" onclick="setMotionAngle(this,'lateral')">Lateral</button><button onclick="setMotionAngle(this,'frontal')">Frontal</button><button onclick="setMotionAngle(this,'lenta')">Cámara lenta</button></div><div class="phase-strip"><span class="active">Preparación</span><span>Inicio</span><span>Trabajo</span><span>Final</span></div><div class="guide-card"><b>Claves técnicas</b><div class="cue">Posición estable antes de iniciar.</div><div class="cue">Controla el recorrido y evita compensaciones.</div><div class="cue">Detén la serie cuando la técnica se deteriore.</div></div><div class="guide-card"><b>Alternativas y escalados</b>${alts.map(a=>`<div class="listitem"><span>${a}</span><button class="secondary" onclick="closeSportMovement();setTimeout(()=>openSportMovement('${a.replace(/'/g,"\\'")}'),100)">Ver</button></div>`).join('')}</div></div>`;let m=document.createElement('div');m.id='sportMovementModal';m.className='modal open';m.innerHTML=html;document.body.appendChild(m)}
function closeSportMovement(){document.getElementById('sportMovementModal')?.remove()}
function setMotionAngle(btn,mode){btn.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');let p=document.querySelector('#sportMotion .person');if(!p)return;p.style.transform=mode==='frontal'?'scaleX(.72)':mode==='lenta'?'scale(1.05)':'';p.style.animationDuration=mode==='lenta'?'5s':'2.5s'}
function renderSportNutrition(){const w=world(),sp=currentSport();let banner=document.getElementById('sportNutritionLive');if(!banner){banner=document.createElement('div');banner.id='sportNutritionLive';let sec=$('nutrition');sec.insertBefore(banner,sec.firstChild)}banner.innerHTML=`<div class="sport-nutrition-banner" style="${sportStyle()}"><div class="row"><div><span class="primary-sport">${sp.emoji} ${sp.name}</span><h3 style="margin:5px 0">${w.nutrition.title}</h3></div><button class="secondary" onclick="go('sports')">Cambiar</button></div><p>${w.nutrition.text}</p><div>${w.nutrition.focus.map(x=>`<span class="chip">${x}</span>`).join('')}</div></div>`}

